{
  "document_metadata": {
    "title": "The Energy Policy Act of 2005",
    "document_number": "Pub. L. No. 109-58",
    "type_of_wind_farm": "Offshore"
  },
  "regulatory_constraints": [
    {
      "type": "Jurisdictional",
      "requirement": "The Secretary of the Interior has the authority to issue leases, easements, or rights-of-way on the Outer Continental Shelf (OCS) for the purpose of renewable energy development, including wind energy development.",
      "scope": "Outer Continental Shelf",
      "source": "43 U.S.C. § 1337(p)(1)(C)",
      "related_domains": "Jurisdictional"
    },
    {
      "type": "Jurisdictional",
      "requirement": "The Secretary of the Interior delegated this authority to the former Minerals Management Service (MMS), now BOEM.",
      "scope": "Outer Continental Shelf",
      "source": "43 U.S.C. § 1337(p)(1)(C)",
      "related_domains": "Jurisdictional"
    },
    {
      "type": "Jurisdictional",
      "requirement": "BOEM promulgated final regulations implementing this authority at 30 CFR Part 585.",
      "scope": "Outer Continental Shelf",
      "source": "30 CFR Part 585",
      "related_domains": "Jurisdictional"
    },
    {
      "type": "Jurisdictional",
      "requirement": "The issuance of leases and subsequent approval of wind energy development on the OCS is a staged decision-making process with four distinct phases: (1) planning; (2) lease issuance; (3) approval of a site assessment plan (SAP); and, (4) approval of a construction and operation plan (COP).",
      "scope": "Outer Continental Shelf",
      "source": "30 CFR Part 585",
      "related_domains": "Jurisdictional"
    },
    {
      "type": "Jurisdictional",
      "requirement": "The competitive lease issuance process is set forth at 30 CFR 585.210 – 585.225, and the noncompetitive process is set forth at 30 CFR 585.230 – 585.232.",
      "scope": "Outer Continental Shelf",
      "source": "30 CFR 585.210 – 585.225, 30 CFR 585.230 – 585.232",
      "related_domains": "Jurisdictional"
    },
    {
      "type": "Jurisdictional",
      "requirement": "A commercial lease gives the lessee the exclusive right to subsequently seek BOEM approval for the development of the leasehold. The lease does not grant the lessee the right to construct any facilities; rather, the lease grants the right to use the leased area to develop its plans, which must be approved by BOEM before the lessee can move on to the next stage of the process.",
      "scope": "Outer Continental Shelf",
      "source": "30 CFR 585.600 and 585.601",
      "related_domains": "Jurisdictional"
    }
  ],
  "regulatory_entities": [
    {
      "entity_name": "Secretary of the Interior",
      "jurisdiction": "Federal",
      "role": "Grants authority for renewable energy development, including wind energy, on the Outer Continental Shelf"
    },
    {
      "entity_name": "Minerals Management Service (MMS)",
      "jurisdiction": "Federal",
      "role": "Former agency that was delegated authority from the Secretary of the Interior for renewable energy development on the Outer Continental Shelf"
    },
    {
      "entity_name": "Bureau of Ocean Energy Management (BOEM)",
      "jurisdiction": "Federal",
      "role": "Current agency that was delegated authority from the Secretary of the Interior for renewable energy development on the Outer Continental Shelf"
    }
  ]
}

